PRAGMA journal_mode=WAL;
PRAGMA busy_timeout=5000;
PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, username TEXT UNIQUE NOT NULL, full_name TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','translator','cleaner','typesetter')), salt TEXT NOT NULL, password_hash TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS user_roles(user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, role TEXT NOT NULL CHECK(role IN ('translator','cleaner','typesetter')), PRIMARY KEY(user_id,role));
CREATE TABLE IF NOT EXISTS user_permissions(user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, permission TEXT NOT NULL CHECK(permission IN ('manager','senior_cleaner','senior_translator')), PRIMARY KEY(user_id,permission));
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS series(id INTEGER PRIMARY KEY, title TEXT NOT NULL, is_ongo INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS chapters(id INTEGER PRIMARY KEY, series_id INTEGER NOT NULL REFERENCES series(id) ON DELETE CASCADE, number TEXT NOT NULL, is_ongo INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, UNIQUE(series_id,number));
CREATE TABLE IF NOT EXISTS work_access(user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, series_id INTEGER NOT NULL REFERENCES series(id) ON DELETE CASCADE, PRIMARY KEY(user_id,series_id));
CREATE TABLE IF NOT EXISTS series_defaults(series_id INTEGER NOT NULL REFERENCES series(id) ON DELETE CASCADE, stage TEXT NOT NULL CHECK(stage IN ('translation','clean','typing')), user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, fee_cents INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, PRIMARY KEY(series_id,stage));
CREATE TABLE IF NOT EXISTS stages(chapter_id INTEGER NOT NULL REFERENCES chapters(id) ON DELETE CASCADE, stage TEXT NOT NULL CHECK(stage IN ('translation','clean','typing')), status TEXT NOT NULL DEFAULT 'waiting' CHECK(status IN ('waiting','in_progress','completed')), uploaded_at TEXT, uploaded_by INTEGER REFERENCES users(id), PRIMARY KEY(chapter_id,stage));
CREATE TABLE IF NOT EXISTS assignments(id INTEGER PRIMARY KEY, chapter_id INTEGER NOT NULL REFERENCES chapters(id) ON DELETE CASCADE, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, stage TEXT NOT NULL CHECK(stage IN ('translation','clean','typing')), assignment_type TEXT NOT NULL DEFAULT 'fixed' CHECK(assignment_type IN ('fixed','assistant')), fee_cents INTEGER NOT NULL DEFAULT 0, due_at TEXT NOT NULL, created_at TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, UNIQUE(chapter_id,stage,user_id));
CREATE TABLE IF NOT EXISTS uploads(id INTEGER PRIMARY KEY, assignment_id INTEGER NOT NULL REFERENCES assignments(id) ON DELETE CASCADE, file_name TEXT NOT NULL, stored_path TEXT NOT NULL, uploaded_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reviews(id INTEGER PRIMARY KEY, upload_id INTEGER NOT NULL REFERENCES uploads(id) ON DELETE CASCADE, status TEXT NOT NULL DEFAULT 'awaiting' CHECK(status IN ('awaiting','revision','approved')), note TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS penalties(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, assignment_id INTEGER REFERENCES assignments(id) ON DELETE SET NULL, amount_cents INTEGER NOT NULL DEFAULT 0, rate_percent REAL NOT NULL DEFAULT 2, reason TEXT NOT NULL, kind TEXT NOT NULL DEFAULT 'manual', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS notices(id INTEGER PRIMARY KEY, message TEXT NOT NULL, created_at TEXT NOT NULL, seen INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS upload_receipts(upload_key TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,assignment_id INTEGER NOT NULL REFERENCES assignments(id) ON DELETE CASCADE,upload_id INTEGER NOT NULL REFERENCES uploads(id) ON DELETE CASCADE,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS stage_completions(chapter_id INTEGER NOT NULL,stage TEXT NOT NULL,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,completed_at TEXT NOT NULL,PRIMARY KEY(chapter_id,stage),FOREIGN KEY(chapter_id,stage) REFERENCES stages(chapter_id,stage) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS completions_month_user ON stage_completions(completed_at,user_id);
CREATE INDEX IF NOT EXISTS uploads_assignment ON uploads(assignment_id,id DESC);
CREATE INDEX IF NOT EXISTS assignments_user_active ON assignments(user_id,active,chapter_id);
CREATE INDEX IF NOT EXISTS assignments_chapter_active ON assignments(chapter_id,active,stage);
CREATE INDEX IF NOT EXISTS reviews_upload ON reviews(upload_id,id DESC);
CREATE INDEX IF NOT EXISTS stages_status_date ON stages(status,uploaded_at,stage);
CREATE UNIQUE INDEX IF NOT EXISTS one_automatic_penalty_per_assignment ON penalties(assignment_id) WHERE assignment_id IS NOT NULL AND kind='automatic';
CREATE UNIQUE INDEX IF NOT EXISTS one_active_assignment_per_stage ON assignments(chapter_id,stage) WHERE active=1;
CREATE TABLE IF NOT EXISTS login_attempts(ip TEXT PRIMARY KEY,count INTEGER NOT NULL,until_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS pending_file_cleanup(id INTEGER PRIMARY KEY,stored_path TEXT NOT NULL,created_at TEXT NOT NULL);